// Normalize and validate incoming webhook payload.
// Handles: snake_case aliases, { body: {...} } wrappers, whitespace,
// missing optional fields, and enforces that at least one name field
// is present before we hit Jobber.

const raw = $input.first().json;
const src = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;

const pick = (...keys) => {
  for (const k of keys) {
    const v = src[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return String(v).trim();
    }
  }
  return '';
};

const firstName   = pick('firstName', 'first_name', 'FirstName');
const lastName    = pick('lastName', 'last_name', 'LastName');
const companyName = pick('companyName', 'company_name', 'company');
const email       = pick('email', 'emailAddress', 'email_address');
const phone       = pick('phone', 'phoneNumber', 'phone_number', 'mobile');
const street1     = pick('address', 'street', 'street1', 'address_line_1');
const city        = pick('city');
const province    = pick('state', 'province', 'region');
const postalCode  = pick('postalCode', 'postal_code', 'zip', 'zipCode');
const country     = pick('country') || 'AU';

// Jobber requires at least one of: firstName+lastName OR companyName.
if (!companyName && !(firstName || lastName)) {
  return [{
    json: {
      __validationError: true,
      message: 'Missing required fields: provide companyName or firstName/lastName.',
      received: Object.keys(src),
    },
  }];
}

// Build ClientCreateInput, omitting empty optional fields so Jobber
// doesn't reject on empty strings in a billingAddress, etc.
const input = {};
if (firstName)   input.firstName   = firstName;
if (lastName)    input.lastName    = lastName;
if (companyName) input.companyName = companyName;
if (email)       input.emails      = [{ description: 'MAIN', primary: true, address: email }];
if (phone)       input.phones      = [{ description: 'MAIN', primary: true, number: phone }];

const address = {};
if (street1)    address.street1    = street1;
if (city)       address.city       = city;
if (province)   address.province   = province;
if (postalCode) address.postalCode = postalCode;
if (Object.keys(address).length) {
  address.country = country;
  input.billingAddress = address;
}

const query = 'mutation ClientCreate($input: ClientCreateInput!) { clientCreate(input: $input) { client { id firstName lastName companyName } userErrors { message path } } }';

return [{
  json: {
    __validationError: false,
    payload: { query, variables: { input } },
    // Keep a copy of the normalized input for downstream nodes/logging
    normalized: { firstName, lastName, companyName, email, phone, street1, city, province, postalCode, country },
  },
}];

// Classify the Jobber response into a single shape so the webhook
// caller always gets structured JSON, whether the call was a success,
// a GraphQL schema/auth error, user-input errors, or an HTTP failure.

const res = $input.first().json || {};
const statusCode = res.statusCode ?? 0;
const body = res.body ?? res; // fullResponse wraps the body; defensive fallback

// HTTP-level failure (auth, rate limit, 5xx, timeout bubbled as 0).
if (statusCode < 200 || statusCode >= 300) {
  let category = 'http_error';
  if (statusCode === 401 || statusCode === 403) category = 'auth_error';
  else if (statusCode === 429) category = 'rate_limited';
  else if (statusCode >= 500) category = 'upstream_error';
  else if (statusCode === 0) category = 'network_error';

  return [{
    json: {
      success: false,
      error: category,
      statusCode,
      message: category === 'auth_error'
        ? 'Jobber rejected the request. Check that the access token is valid and not expired.'
        : `Jobber returned HTTP ${statusCode}.`,
      details: body,
      responseCode: statusCode === 429 ? 503 : (statusCode >= 500 ? 502 : 502),
    },
  }];
}

// Top-level GraphQL errors (malformed query, schema mismatch, etc.).
if (Array.isArray(body.errors) && body.errors.length) {
  return [{
    json: {
      success: false,
      error: 'graphql_error',
      message: 'Jobber GraphQL returned errors.',
      details: body.errors,
      responseCode: 502,
    },
  }];
}

const result = body?.data?.clientCreate;
if (!result) {
  return [{
    json: {
      success: false,
      error: 'unexpected_response',
      message: 'Jobber response did not include data.clientCreate.',
      details: body,
      responseCode: 502,
    },
  }];
}

// Input-level errors reported by Jobber (bad email format, missing field, ...).
if (Array.isArray(result.userErrors) && result.userErrors.length) {
  return [{
    json: {
      success: false,
      error: 'user_error',
      message: 'Jobber rejected the client input.',
      userErrors: result.userErrors,
      responseCode: 400,
    },
  }];
}

return [{
  json: {
    success: true,
    clientId: result.client?.id,
    client: result.client,
    responseCode: 200,
  },
}];
